function validate(input) {
  const [{ Queries = [] }] = input;
  for (const row of Queries) {
    if (row.some((v) => v === null)) return 'Queries rows may not contain null.';
    const [, , position, rating] = row;
    if (position < 1 || position > 500) return `position must be between 1 and 500, not ${position}.`;
    if (rating < 1 || rating > 5) return `rating must be between 1 and 5, not ${rating}.`;
  }
  return null;
}

