function generate(rand, size) {
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const results = ['Golden Retriever', 'German Shepherd', 'Mule', 'Shirazi', 'Siamese', 'Sphynx', 'Poodle'];
  const Queries = [];
  if (size === 'small') {
    // Power-of-two positions keep every rating / position exact, so rounding never depends on summation order.
    const rows = Math.floor(rand() * 9);
    for (let i = 0; i < rows; i++) {
      Queries.push([pick(['Dog', 'Cat', 'Bird']), pick(results), pick([1, 2, 4, 8, 16, 32, 128, 256]), 1 + Math.floor(rand() * 5)]);
    }
  } else {
    // Group sizes of 150..400 never put the percentage exactly on a rounding half.
    const sizes = [150, 200, 250, 300, 400];
    for (let name = 1, total = 0; ; name++) {
      const count = pick(sizes);
      if (total + count > 2000) break;
      total += count;
      for (let i = 0; i < count; i++) Queries.push([`Q${name}`, pick(results), 1 + Math.floor(rand() * 500), 1 + Math.floor(rand() * 5)]);
    }
    for (let i = Queries.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [Queries[i], Queries[j]] = [Queries[j], Queries[i]];
    }
  }
  return [{ Queries }];
}
